import { createHash } from 'node:crypto';
import { readFile, writeFile, copyFile, mkdir } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const output = process.argv[2];
if (!output) throw new Error('Pass the explicit standalone output directory containing the npm tarball.');
const destination = resolve(output);
const manifest = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'));
const filename = `noetra-${manifest.version}.tgz`;
const archive = await readFile(resolve(destination, filename));
await mkdir(destination, { recursive: true });
for (const name of ['Install-NOETRA.cmd', 'Install-NOETRA.ps1', 'START-HERE.md']) await copyFile(resolve(root, 'scripts/windows', name), resolve(destination, name));
await copyFile(resolve(root, 'docs/VERIFICATION.md'), resolve(destination, 'VERIFICATION.md'));
await copyFile(resolve(root, 'docs/VISUAL-UPGRADE.md'), resolve(destination, 'VISUAL-UPGRADE.md'));
await copyFile(resolve(root, 'docs/RECONSTRUCTION.md'), resolve(destination, 'RECONSTRUCTION.md'));
await copyFile(resolve(root, 'LICENSE'), resolve(destination, 'LICENSE'));
await writeFile(resolve(destination, 'SHA256SUMS.json'), JSON.stringify({ [filename]: createHash('sha256').update(archive).digest('hex') }, null, 2) + '\n');
console.log(JSON.stringify({ directory: destination, filename, sha256: createHash('sha256').update(archive).digest('hex') }));
